mkdir -p src/db && cat > src/db/schema.ts <<'EOF'
import { sql } from "drizzle-orm";
import { sqliteTable, text } from "drizzle-orm/sqlite-core";

export const users = sqliteTable("users", {
  id: text("id").primaryKey(),
  email: text("email").notNull().unique(),
  name: text("name").notNull(),
  createdAt: text("created_at")
    .notNull()
    .default(sql`(date('now'))`),
});

export type UserRow = typeof users.$inferSelect;
export type NewUserRow = typeof users.$inferInsert;
EOF
cat > src/db/index.ts <<'EOF'
import Database from "better-sqlite3";
import { drizzle } from "drizzle-orm/better-sqlite3";
import { migrate } from "drizzle-orm/better-sqlite3/migrator";
import path from "node:path";
import * as schema from "./schema";

const url = process.env.DATABASE_URL ?? "./data/app.db";

// Reuse the connection across Next.js dev hot reloads.
const globalForDb = globalThis as unknown as { sqlite?: Database.Database };

const sqlite = globalForDb.sqlite ?? new Database(url);
sqlite.pragma("journal_mode = WAL");
sqlite.pragma("foreign_keys = ON");
if (process.env.NODE_ENV !== "production") globalForDb.sqlite = sqlite;

export const db = drizzle(sqlite, { schema });

/** Apply pending migrations from ./drizzle. Also run via `npm run db:migrate`. */
export function runMigrations() {
  migrate(db, { migrationsFolder: path.join(process.cwd(), "drizzle") });
}
EOF
cat > src/db/migrate.ts <<'EOF'
import { runMigrations } from "./index";

runMigrations();
console.log("Migrations applied");
EOF
cat > src/db/seed.ts <<'EOF'
import { db, runMigrations } from "./index";
import { users } from "./schema";

runMigrations();
db.insert(users)
  .values([
    { id: "1", email: "ada@example.com", name: "Ada", createdAt: "2026-01-04" },
    { id: "2", email: "grace@example.com", name: "Grace", createdAt: "2026-02-11" },
  ])
  .onConflictDoNothing()
  .run();
console.log("Seeded");
EOF
cat > src/db/queries.ts <<'EOF'
import { asc, eq } from "drizzle-orm";
import { db } from "./index";
import { users, type NewUserRow, type UserRow } from "./schema";

export function selectUsers(): UserRow[] {
  return db.select().from(users).orderBy(asc(users.createdAt), asc(users.id)).all();
}

export function selectUserById(id: string): UserRow | undefined {
  return db.select().from(users).where(eq(users.id, id)).get();
}

export function selectFirstUser(): UserRow | undefined {
  return db.select().from(users).orderBy(asc(users.createdAt), asc(users.id)).limit(1).get();
}

export function insertUser(user: NewUserRow): UserRow {
  return db.insert(users).values(user).returning().get();
}
EOF
cat > src/lib/users.ts <<'EOF'
import { insertUser, selectFirstUser, selectUserById, selectUsers } from "@/db/queries";
import type { UserRow } from "@/db/schema";

export type User = UserRow;

export async function listUsers(): Promise<User[]> {
  return selectUsers();
}

export async function getUser(id: string): Promise<User | undefined> {
  return selectUserById(id);
}

export async function createUser(input: Pick<User, "email" | "name">): Promise<User> {
  return insertUser({ id: crypto.randomUUID(), ...input });
}

// TODO: there is no real session handling yet — the dashboard just picks the first user.
export async function getCurrentUser(): Promise<User | undefined> {
  return selectFirstUser();
}
EOF
cat > drizzle.config.ts <<'EOF'
import { defineConfig } from "drizzle-kit";

export default defineConfig({
  dialect: "sqlite",
  schema: "./src/db/schema.ts",
  out: "./drizzle",
  dbCredentials: { url: process.env.DATABASE_URL ?? "./data/app.db" },
});
EOF
cat > .env.example <<'EOF'
# SQLite database file path (relative to project root)
DATABASE_URL=./data/app.db
EOF
printf '\n# local database\n/data/\n!.env.example\n' >> .gitignore
npm pkg set scripts.db:generate="drizzle-kit generate" scripts.db:migrate="tsx --env-file-if-exists=.env src/db/migrate.ts" scripts.db:seed="tsx --env-file-if-exists=.env src/db/seed.ts"
mkdir -p data && npx drizzle-kit generate 2>&1 | tail -5
grep -n "serverExternal" next.config.ts; cat next.config.ts

